import React, { useState } from 'react';
import './App.css';

function App() {
  const [sceneText, setSceneText] = useState('');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState(null);
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setResults(null);
    try {
      const response = await fetch('http://localhost:5000/search', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: sceneText })
      });
      const data = await response.json();
      if (Array.isArray(data)) {
        setResults(data);
      } else if (data && data.error) {
        setError(data.error);
      } else {
        setError('Erro inesperado ao buscar resultados.');
      }
    } catch (err) {
      setError('Erro de conexão com o servidor.');
    }
    setLoading(false);
  };

  return (
    <div className="app-container">
      <h1>ShotFinder</h1>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: 18 }}>
          <label>Descreva a cena ou digite o nome do filme/série:</label><br />
          <textarea
            rows={4}
            value={sceneText}
            onChange={e => setSceneText(e.target.value)}
            placeholder="Ex: Um homem com capa preta luta contra vilões em uma cidade escura."
          />
        </div>
        <button type="submit" disabled={!sceneText || loading} style={{ width: '100%' }}>
          {loading ? 'Buscando...' : 'Buscar filme/série'}
        </button>
      </form>
      {error && (
        <div style={{ color: '#f87171', background: '#1e293b', borderRadius: 8, padding: 12, marginTop: 24, textAlign: 'center', fontWeight: 500 }}>
          {error}
        </div>
      )}
      {results && (
        <div className="resultados">
          <h2 style={{ textAlign: 'center', color: '#f1f5f9', fontSize: '1.3rem', marginBottom: 18 }}>Resultados:</h2>
          {results.length === 0 && (
            <div style={{ textAlign: 'center', marginTop: 16 }}>
              <p>Nenhum resultado encontrado.</p>
              <div style={{
                background: '#334155',
                color: '#38bdf8',
                borderRadius: 8,
                padding: 14,
                margin: '18px auto 0 auto',
                maxWidth: 340,
                fontSize: '0.98rem',
                lineHeight: 1.5
              }}>
                <strong>Dicas para melhorar sua busca:</strong>
                <ul style={{ textAlign: 'left', margin: '10px 0 0 18px', padding: 0 }}>
                  <li>Use nomes de personagens, frases marcantes ou o nome do filme/série.</li>
                  <li>Experimente uma descrição mais detalhada da cena.</li>
                  <li>Evite termos muito genéricos ou curtos.</li>
                </ul>
              </div>
            </div>
          )}
          {results.map((item) => (
            <div key={item.id} className="result-card">
              <img src={item.poster} alt={item.title} />
              <div className="result-info">
                <h3>{item.title} {item.year && <span style={{ color: '#64748b', fontWeight: 400 }}>({item.year})</span>}</h3>
                <p><strong>Sinopse:</strong> {item.overview}</p>
                <p><strong>Elenco:</strong> {item.cast}</p>
                <p><strong>Onde assistir:</strong> {item.streaming && item.streaming.length > 0 ? item.streaming.join(', ') : 'Não encontrado'}</p>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default App;
